-- PT121-S4-Q4. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT121-S4-Q4$batch12$ AND q.stimulus=$batch12$My suspicion that there is some truth to astrology has been confirmed. Most physicians I have talked to believe in it.$batch12$ AND q.prompt=$batch12$The flawed pattern of reasoning in the argument above is most similar to that in which one of the following?$batch12$ AND q.correct_choice=$batch12$B$batch12$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT121-S4-Q4$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT121-S4-Q4$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$There is some truth to astrology.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Most physicians the author has talked to believe in it.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Physicians aren't experts on astrology. The argument relies on authorities speaking outside their field.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Accept a claim because people with unrelated expertise believe it.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT121-S4-Q4$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This dismisses theories because of the person's conduct. That attacks the source, a different flaw.$batch12$), ($batch12$B$batch12$, $batch12$The author trusts biology professors on whether social programs are wasteful. Same out-of-field appeal.$batch12$), ($batch12$C$batch12$, $batch12$Physicists are the right experts on quantum mechanics. Reasonable.$batch12$), ($batch12$D$batch12$, $batch12$This moves from what engineers say to what they do.$batch12$), ($batch12$E$batch12$, $batch12$This relies on many sighting reports, not on expert belief.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT121-S4-Q4$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
